import java.util.*;

import org.slf4j.*;

public class Main {
    private static final Logger log = LoggerFactory.getLogger(Main.class);

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split(";", -1);
            MDC.put("paket", d[0]);
            try {
                log.info("Mengirim ke {}", d[1]);
                if (d[1].isEmpty()) {
                    log.warn("Alamat kosong");
                } else {
                    log.info("Paket terkirim");
                }
            } finally {
                MDC.remove("paket");
            }
        }
        log.info("Semua paket diproses");
    }
}
